var seen = new Map();
var node = (at, bytes, key="local/codex:one") => ({key, last_growth_at:at, last_growth_bytes:bytes});
var t0="2026-10-19T19:00:00Z", t1="2026-10-19T19:00:05Z", t2="2026-10-19T19:00:10Z";
var update = nodes => DrigaConsole.observationPulses(seen,nodes);
if(update([node(t0,100)]).length) throw Error("initial history pulsed");
if(update([node(t0,100)]).length) throw Error("unchanged refresh pulsed");
var pulses=update([node(t1,12288)]);
if(pulses.length!==1 || pulses[0].label!=="+12 KB transcript") throw Error("new growth did not pulse with byte label");
if(update([node(t1,12288),node(t1,12288)]).length) throw Error("duplicate refresh pulsed");
if(update([node(t0,100)]).length || update([node(t1,12288)]).length) throw Error("out-of-order refresh replayed growth");
if(update([node(t2,2,"peer/codex:one")]).length) throw Error("new machine inherited baseline");
if(update([node(null,0,"local/codex:cpu")]).length) throw Error("CPU-only observation pulsed");
if(update([node(t2,2,"local/codex:cpu")]).length!==1) throw Error("first growth after CPU-only observation missing");
if(update([node(t2,500)]).length!==1) throw Error("second advance missing");
if(DrigaConsole.transcriptSize(0)!=="0 B" || DrigaConsole.transcriptSize(512)!=="512 B") throw Error("small byte labels");
